import {createGardenState,stepGarden} from '../../../../src/js/garden/GardenSimulation.js';
import {GARDEN_ART} from '../../../../src/js/garden/GardenArt.js';
import {GARDEN as C,GARDEN_PLATFORM_BY_ID,GARDEN_ENEMIES,GARDEN_WATERS,GARDEN_FINAL_START,gardenPlatforms} from '../../../../src/js/garden/GardenLevel.js';
import {ToyRoomPhase} from '../../../../src/js/toy-room/ToyRoomPhase.js';
const check=(value,label)=>{if(!value)throw Error(label);};
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function prepared(phase){for(let i=0;i<200&&!phase.ready;i++){if(phase.error)throw Error(phase.error);await wait(50);}check(phase.ready,'Artes prontas');}
export async function start(difficulty='NORMAL'){
 const g=review.game;await g.assetsReady;g.startDebugPhase('garden',difficulty);const p=g.state.toyRoomInstance.instance.garden;await prepared(p);g.setPaused(true);p.state.stage='RUNNING';p.state.age=5;return true;
}
export async function audit(){
 const g=review.game,r=g.state.toyRoomInstance.instance,phase=r.garden,renderer=phase.renderer,shots=[];let frames=0;
 for(const [key,set]of Object.entries(GARDEN_ART.sets)){
  const image=renderer.images.get(set.file);check(image,'Imagem carregada');const canvas=document.createElement('canvas');canvas.width=image.width;canvas.height=image.height;const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0);const data=ctx.getImageData(0,0,canvas.width,canvas.height).data;
  for(const f of set.frames){let opaque=0,transparent=0,bottom=0;for(let y=0;y<f.h;y++)for(let x=0;x<f.w;x++){const a=data[((f.y+y)*canvas.width+f.x+x)*4+3];if(a>128)opaque++;if(!a)transparent++;if(a)bottom=y+1;}check(opaque>100,'Recorte visível');if(key.startsWith('menina')){check(transparent>100,'Alfa real da menina');check(bottom===f.anchorY,'Pés ancorados');}frames++;}
 }
 // Nenhuma fresta entre repetições da textura de uma mesma faixa fixa.
 for(const type of ['wood','soil','grass','gravel']){
  const canvas=document.createElement('canvas');canvas.width=1000;canvas.height=280;const ctx=canvas.getContext('2d');ctx.fillStyle='#ff00ff';ctx.fillRect(0,0,1000,280);renderer.terrain(ctx,{x:0,y:100,w:1000,type,ground:true},280);const pixels=ctx.getImageData(40,115,920,120).data;
  for(let i=0;i<pixels.length;i+=4)check(!(pixels[i]===255&&pixels[i+1]===0&&pixels[i+2]===255),'Chão contínuo sem frestas: '+type);
 }
 // A base da pedra precisa chegar à água, sem uma faixa de fundo aparente.
 {const canvas=document.createElement('canvas');canvas.width=200;canvas.height=720;const ctx=canvas.getContext('2d');ctx.fillStyle='#ff00ff';ctx.fillRect(0,0,200,720);renderer.terrain(ctx,{x:20,y:520,w:160,type:'stone'},720);const pixels=ctx.getImageData(100,580,1,70).data;for(let i=0;i<pixels.length;i+=4)check(!(pixels[i]===255&&pixels[i+1]===0&&pixels[i+2]===255),'Pedra em contato com a água');}
 // Grama cobre pixels reais dos sapatos, sem mover o estado da personagem.
 {const s=createGardenState();s.stage='RUNNING';Object.assign(s.player,{x:1430,y:GARDEN_PLATFORM_BY_ID.get('primeira-grama').y,terrain:'grass',discomfort:1});const canvas=document.createElement('canvas');canvas.width=200;canvas.height=180;const ctx=canvas.getContext('2d');ctx.translate(100-s.player.x,120-s.player.y);renderer.sprite(ctx,'menina-desconforto-v1',0,s.player.x,s.player.y,92);const before=ctx.getImageData(55,95,90,28).data,state=JSON.stringify(s);renderer.grassFront(ctx,s,gardenPlatforms(s.time,s,s.player.x));const after=ctx.getImageData(55,95,90,28).data;let covered=0;for(let i=0;i<before.length;i+=4)if(before[i+3]>120&&before[i]>before[i+1]*1.2&&after[i+1]>before[i+1]+10)covered++;check(covered>15,'Pés enterrados pela grama de primeiro plano');check(JSON.stringify(s)===state,'Oclusão não move física');}
 // A vegetação inteira fica na frente, translúcida e imóvel mesmo longe da menina.
 {const ground=GARDEN_PLATFORM_BY_ID.get('primeira-grama'),s=createGardenState(),canvas=document.createElement('canvas');canvas.width=ground.w;canvas.height=100;const ctx=canvas.getContext('2d');ctx.translate(-ground.x,-ground.y+90);renderer.grassFront(ctx,s,[ground]);const before=ctx.getImageData(0,0,canvas.width,100).data;let left=0,right=0,max=0;for(let i=3;i<before.length;i+=4){max=Math.max(max,before[i]);if(before[i]>0){if((i/4)%canvas.width<150)left++;if((i/4)%canvas.width>canvas.width-150)right++;}}check(left>100&&right>100,'Grama cobre toda a faixa');check(max>100&&max<245,'Folhagem translúcida');ctx.clearRect(ground.x,ground.y-90,canvas.width,100);s.time=5;Object.assign(s.player,{x:2500,y:100,onGround:false});renderer.grassFront(ctx,s,[ground]);const after=ctx.getImageData(0,0,canvas.width,100).data;check(before.every((v,i)=>v===after[i]),'Grama fixa no mundo, independente da personagem e do salto');}
 // As duas margens de cada rio recebem pintura de água sob seu contorno irregular.
 {const canvas=document.createElement('canvas');canvas.width=80;canvas.height=20;const ctx=canvas.getContext('2d'),grounds=[...GARDEN_PLATFORM_BY_ID.values()].filter(p=>p.ground);for(const water of GARDEN_WATERS){for(const edge of [water.x,water.x+water.w]){const banks=grounds.flatMap(p=>[p.x,p.x+p.w]).filter(x=>Math.abs(x-edge)<80),bank=banks.sort((a,b)=>Math.abs(a-edge)-Math.abs(b-edge))[0];check(bank!==undefined,'Margem encontrada');ctx.setTransform(1,0,0,1,40-bank,-C.waterY+25);ctx.fillStyle='#ff00ff';ctx.fillRect(bank-40,C.waterY-25,80,20);renderer.waterFront(ctx,{time:0},bank-40,bank+40,C.waterY+100,[]);const pixel=ctx.getImageData(40,10,1,1).data;check(pixel[1]>0,'Água toca margem '+water.id);}}}
 // A água frontal chega à borda, mas não tinge o interior de nenhuma margem.
 {const grounds=[...GARDEN_PLATFORM_BY_ID.values()].filter(p=>p.ground),canvas=document.createElement('canvas');canvas.width=120;canvas.height=120;const ctx=canvas.getContext('2d');for(const water of GARDEN_WATERS){const banks=grounds.filter(p=>Math.abs(p.x-water.x-water.w)<80||Math.abs(p.x+p.w-water.x)<80);for(const bank of banks){const x=Math.abs(bank.x-water.x-water.w)<80?bank.x:bank.x+bank.w-100;ctx.setTransform(1,0,0,1,-x,-C.waterY+20);ctx.fillStyle='#b87040';ctx.fillRect(x,C.waterY-20,120,120);const before=ctx.getImageData(60,60,1,1).data;renderer.waterFront(ctx,{time:0},x,x+120,C.waterY+100,[bank]);const after=ctx.getImageData(60,60,1,1).data;check(before.every((v,i)=>v===after[i]),'Água excluída do corpo da margem '+bank.id);}}}
 // Toda árvore tem raízes inteiras sobre seu patamar, inclusive nas maiores alturas.
 for(const tree of renderer.sceneryItems.trees){const ground=GARDEN_PLATFORM_BY_ID.get(tree.groundId);check(tree.x>=ground.x&&tree.x+tree.w<=ground.x+ground.w,'Base completa da árvore apoiada');check(Math.abs(tree.y+tree.h-ground.y-4)<.01,'Raízes na altura real do chão');for(const [width,height]of [[1280,800],[390,844],[844,390]]){const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const original=renderer.canvas;renderer.canvas=canvas;const frame=renderer.frame({...phase.state,player:{...phase.state.player,x:tree.x+tree.w/2}});renderer.canvas=original;check(tree.y*frame.scale+frame.oy>=80,'Copa dentro do enquadramento vertical');}}
 // O miolo ilustrado encosta nos pés: mede somente a pintura, sem preencher a folga com cor de fundo.
 for(const type of ['soil','wood','gravel']){const tile=renderer.surfaceTile(type),offset=type==='soil'?18:type==='wood'?10:10,ctx=tile.getContext('2d'),pixels=ctx.getImageData(0,0,tile.width,tile.height).data;for(let x=0;x<tile.width;x+=3){let top=0;while(top<tile.height&&pixels[(top*tile.width+x)*4+3]<180)top++;check(top-offset<=3,'Pintura toca o apoio em '+type+' coluna '+x);}}
 // Nenhuma fresta do fundo atravessa a união de dois patamares de terra.
 {const all=[...GARDEN_PLATFORM_BY_ID.values()].filter(p=>p.ground),canvas=document.createElement('canvas');canvas.width=20;canvas.height=850;const ctx=canvas.getContext('2d');for(const a of all){const b=all.find(p=>Math.abs(p.x-a.x-a.w)<.01);if(!b)continue;ctx.setTransform(1,0,0,1,10-b.x,0);ctx.fillStyle='#ff00ff';ctx.fillRect(b.x-10,0,20,850);renderer.terrainBodies(ctx,[a,b],850);const pixels=ctx.getImageData(9,Math.max(a.y,b.y)+5,2,700-Math.max(a.y,b.y)).data;for(let i=0;i<pixels.length;i+=4)check(!(pixels[i]===255&&pixels[i+1]===0&&pixels[i+2]===255),'Emenda sem fresta '+b.id);}}
 // A atuação das pernas usa quatro pinturas distintas e pausa conserva o relógio.
 {const observed=new Set(),draw=renderer.sprite;renderer.sprite=function(ctx,set,index,...args){if(set==='menina-pedrinhas-v2')observed.add(index);return draw.call(this,ctx,set,index,...args);};try{for(let i=0;i<16;i++){phase.state=createGardenState();phase.state.stage='RUNNING';phase.state.time=i/36;Object.assign(phase.state.player,{x:4400,y:590,onGround:true,terrain:'gravel',vx:410,discomfort:1});phase.render();}}finally{renderer.sprite=draw;}check(observed.size===4,'Quatro poses reais de desequilíbrio nas pedrinhas');}
 const unchanged=JSON.stringify(phase.state);phase.render();check(JSON.stringify(phase.state)===unchanged,'Desenho puro');const f=renderer.frame(phase.state);phase.state.player.y-=240;const jump=renderer.frame(phase.state);check(f.scale===jump.scale&&f.oy===jump.oy,'Câmera lateral fixa');
 const locations=[['contato-solo',GARDEN_PLATFORM_BY_ID.get('trecho-0-caminho-relevo-2').x+100],['contato-grama',GARDEN_PLATFORM_BY_ID.get('primeira-grama').x+100],['roda-apoio',5050],['relevo-primeiro',1750],['relevo-longo',GARDEN_PLATFORM_BY_ID.get('trecho-6-gramado-relevo-2').x+80],['margem-saida',3240],['casa',150],['grama',1750],['margem-inicial',2300],['agua-primeira',2700],['troca-de-terreno',3950],['pedrinhas',4400],['roda',5050],['nuvens',5650],['lagarta-vermelha',6500],['rio-com-formiga',GARDEN_ENEMIES.find(e=>e.route).x],['paisagem-longa',C.width*.55],['quatro-nuvens',GARDEN_FINAL_START+1050],['piquenique',C.goal]];
 for(const [label,sceneX]of locations){let x=sceneX;phase.state=createGardenState();phase.state.stage=label==='piquenique'?'COMPLETE':'RUNNING';phase.state.time=12;phase.state.age=4;const wheelSupport=label==='roda-apoio'?gardenPlatforms(12,phase.state,5050).filter(p=>p.rotating).sort((a,b)=>b.y-a.y)[0]:null;if(wheelSupport)x=wheelSupport.x+wheelSupport.w/2;const support=wheelSupport??gardenPlatforms(12,phase.state,x).filter(p=>x>=p.x&&x<=p.x+p.w).sort((a,b)=>a.y-b.y)[0];Object.assign(phase.state.player,{x,y:support?.y??480,onGround:Boolean(support),support:support?.id??null,terrain:support?.type??'cloud',discomfort:['grama','contato-grama','pedrinhas'].includes(label)?1:0,vx:label==='pedrinhas'?410:label==='grama'?100:0});phase.state.fairy.x=x;phase.state.fairy.y=phase.state.player.y-135;if(label==='lagarta-vermelha'){const e=phase.state.enemies.find(e=>e.type==='caterpillar');e.hp=1;e.x=x+110;}phase.render();shots.push({label,data:phase.canvas.toDataURL()});}
 for(const [label,kind]of [['resgate','fall'],['desnorteada','hurt']]){phase.difficulty='EASY';phase.state=createGardenState('EASY');phase.state.stage='RUNNING';phase.state.hp=1;if(kind==='fall')Object.assign(phase.state.player,{x:720,y:900,onGround:false});else{const e=phase.state.enemies.find(e=>e.type==='caterpillar');Object.assign(phase.state.player,{x:e.x,y:e.y,onGround:false});phase.state.trail=['grama-da-margem','pedrinhas-da-roda','primeiros-bichinhos'];}stepGarden(phase.state,{},1/60,'EASY');check(phase.state.stage===('fall'===kind?'RESCUING':'DISORIENTED'),'EASY recupera sem derrota');stepGarden(phase.state,{},.2,'EASY');phase.render();shots.push({label,data:phase.canvas.toDataURL()});check(!g.isGameOver(),'Host não termina EASY');}
 phase.difficulty='NORMAL';phase.state=createGardenState();phase.state.stage='RUNNING';g.setPaused(false);const original=Object.getOwnPropertyDescriptor(navigator,'getGamepads');try{Object.defineProperty(navigator,'getGamepads',{configurable:true,value:()=>[{connected:true,axes:[.8],buttons:Array.from({length:16},(_,i)=>({pressed:i===0}))}]});const pad=phase.input.sample();check(pad.x===.8&&pad.jump,'Gamepad simultâneo');}finally{if(original)Object.defineProperty(navigator,'getGamepads',original);else delete navigator.getGamepads;}
 const frozen=JSON.stringify(phase.state);window.dispatchEvent(new Event('blur'));phase.update(30);check(JSON.stringify(phase.state)===frozen,'Perda de foco congela');window.dispatchEvent(new Event('focus'));check(!phase.paused,'Foco retoma');g.setPaused(true);
 const canvas=document.createElement('canvas');canvas.width=960;canvas.height=540;const room=new ToyRoomPhase(canvas,null,null,null,{assets:g.assets,bindInputs:false});room.story.state.arenaCompleted=true;room.arena.state.completed=true;room.tutorial.finish();let destroyed=0;room.chase={active:true,campaign:true,state:{stage:'COMPLETE'},update(){},destroy(){destroyed++;}};room.update(150);check(room.garden?.active&&destroyed===1,'Campanha descarta fuga e abre jardim');await prepared(room.garden);
 room.garden.state.stage='RUNNING';const ground=GARDEN_PLATFORM_BY_ID.get('trecho-10-caminho');Object.assign(room.garden.state.player,{x:ground.x+100,y:ground.y,support:ground.id});const saved=room.snapshot();check(saved.toyRoomGarden&&!saved.toyRoomChaseCampaign,'Save ativo só do jardim');room.restore(saved);await prepared(room.garden);check(room.garden.state.player.x===ground.x+100,'Save restaura avanço');const before=JSON.stringify(room.garden.snapshot());room.garden.setPaused(true);room.garden.update(60);check(JSON.stringify(room.garden.snapshot())===before,'Pausa congela relógios');room.garden.state.stage='GAME_OVER';check(room.retryDefeat(),'Retry normal pelo host');const p=room.garden;room.destroy();check(!p.input.installed&&p.renderer.images.size===0&&p.renderer.patterns.size===0&&p.audio.voices.size===0,'Descarte integral');
 return{frames,shots,continuousGround:true,camera:true,transition:true,save:true,pause:true,immortal:true,dispose:true};
}
export function controls(){const phase=review.game.state.toyRoomInstance.instance.garden,canvas=phase.canvas,rect=canvas.getBoundingClientRect();return Object.fromEntries(Object.entries(phase.renderer.controls()).map(([key,b])=>[key,{x:rect.left+b.x/canvas.width*rect.width,y:rect.top+b.y/canvas.height*rect.height}]));}
